import{_ as e,c,o as t,b2 as d}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"C7Copy 复制","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/components/通用组件/c7-copy.md","filePath":"docs/frontend/components/通用组件/c7-copy.md"}'),n={name:"docs/frontend/components/通用组件/c7-copy.md"};function s(r,o,a,i,l,p){return t(),c("div",null,[...o[0]||(o[0]=[d('<h1 id="c7copy-复制" tabindex="-1">C7Copy 复制 <a class="header-anchor vp-link" href="#c7copy-复制" aria-label="Permalink to &quot;C7Copy 复制&quot;">​</a></h1><p>轻量纯文本复制组件：优先 <strong>Clipboard API</strong>，失败或不满足安全上下文时 <strong><code>document.execCommand(&#39;copy&#39;)</code></strong> 降级；可配置 <strong><code>ElMessage</code></strong> 或自定义 <strong><code>notify</code></strong>。</p><p><strong>源码</strong>：<code>quick-ui/src/packages/C7Copy/index.vue</code><br><strong>Dev 页</strong>：开发服务器启动后访问 <code>/dev/c7-copy-e2e</code></p><h2 id="功能概要" tabindex="-1">功能概要 <a class="header-anchor vp-link" href="#功能概要" aria-label="Permalink to &quot;功能概要&quot;">​</a></h2><ul><li><strong><code>text</code></strong>：<code>String</code> / <code>Number</code> / <code>null</code>；<code>null</code>/<code>undefined</code> 按空串参与复制链。</li><li><strong><code>getCopyText(baseText)</code></strong>：可选，同步或 <strong>Promise</strong>，返回最终写入剪贴板的字符串。</li><li><strong><code>mode</code></strong>：<code>button</code> | <code>icon</code> | <code>text</code> | <code>clickable</code>；<code>none</code> 为 <strong><code>clickable</code></strong> 的兼容别名。</li><li><strong><code>beforeCopy</code></strong>：返回严格 <strong><code>false</code></strong> 时中止（不调用 <code>getCopyText</code>、不写剪贴板、不 <code>emit</code>）。</li><li><strong><code>afterCopy</code></strong>：写入成功后、<code>emit(&#39;success&#39;)</code> 之前调用。</li><li><strong>事件</strong>：<code>copy</code>（写入前）、<code>success</code>、<code>error</code>。</li><li><strong><code>notify(type, message)</code></strong>：若传入，成功/失败 <strong>仅</strong>走该回调，不再使用 <strong><code>ElMessage</code></strong>。</li></ul><h2 id="与全局注册" tabindex="-1">与全局注册 <a class="header-anchor vp-link" href="#与全局注册" aria-label="Permalink to &quot;与全局注册&quot;">​</a></h2><p>在 <code>main.js</code> 已调用 <code>installPackages(app)</code> 时，模板中可直接使用 <code>&lt;c7-copy /&gt;</code>（或 <code>&lt;C7Copy /&gt;</code>）。</p><h2 id="相关规格" tabindex="-1">相关规格 <a class="header-anchor vp-link" href="#相关规格" aria-label="Permalink to &quot;相关规格&quot;">​</a></h2><p>OpenSpec 变更：<code>openspec/changes/ui-c7-copy/specs/ui-c7-copy/spec.md</code></p>',9)])])}const m=e(n,[["render",s]]);export{u as __pageData,m as default};
